package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MathUtils_mulAndCheck_TriageGen2Test {









    @Test
    public void testMulAndCheck_NegativeNegative_Overflow() {
        // check for positive overflow with negative a, negative b
        // a >= Long.MAX_VALUE / b (Note: b is negative, so inequality flips in logic)
        // Since a and b are negative, a*b is positive.
        // If a is very small (large magnitude), a*b > MAX_VALUE
        try {
            // Using -1 and Long.MIN_VALUE is tricky due to symmetry and sign, 
            // let's pick values that trigger the branch a >= Long.MAX_VALUE / b
            // If b = -2, Long.MAX_VALUE / -2 is a large negative number.
            // If a = -Long.MAX_VALUE, then a < Long.MAX_VALUE / b is false? 
            // Let's use values that result in a * b > Long.MAX_VALUE
            MathUtils.mulAndCheck(Long.MIN_VALUE / 2, -3L); 
            // Wait, the code says: if (a >= Long.MAX_VALUE / b) ret = a * b; else throw.
            // If a = -10, b = -10. Long.MAX_VALUE / -10 is negative. -10 >= negative is true.
            // To trigger the 'else' (overflow), we need a < Long.MAX_VALUE / b.
            // Since Long.MAX_VALUE / b is a negative number, we need a to be "more negative" than that.
            // Example: b = -1. Long.MAX_VALUE / -1 = -Long.MAX_VALUE. 
            // If a = -Long.MAX_VALUE - 1 (not possible in long), let's use b = -2.
            // Long.MAX_VALUE / -2 = -4611686018427387903.
            // If a = -5000000000000000000L, then a < -46... is true.
            MathUtils.mulAndCheck(-5000000000000000000L, -2L);
            fail("Expected ArithmeticException for negative-negative overflow");
        } catch (ArithmeticException e) {
            assertEquals("overflow: multiply", e.getMessage());
        }
    }










}

