public class MathUtils_mulAndCheck_TriageGen2Test {













    @Test
    public void testMulAndCheck_NegativePositive_Overflow() {
        // check for negative overflow with negative a, positive b
        // if (Long.MIN_VALUE / b <= a)
        try {
            // Long.MIN_VALUE / 2 is a large negative number. 
            // If a is smaller than that (e.g., Long.MIN_VALUE), it overflows.
            MathUtils.mulAndCheck(Long.MIN_VALUE, 2L);
            fail("Expected ArithmeticException for negative-positive overflow");
        } catch (ArithmeticException e) {
            assertEquals("overflow: multiply", e.getMessage());
        }
    }






}

